"""Build sequence S0..S10, generated by code from the flows and the dependency graph (spec 7.1).

S5 is the vertical slice of the *primary* flow and stops for user feedback. S6 builds every other
screen in parallel groups (one group per flow, or per surface for screens in no flow); each group
owns a set of path globs derived from the screens' routes, and no two groups own overlapping
paths. ``owns`` globs are literal paths (``[id]`` is a literal Expo Router segment, not a glob
class) with ``**`` meaning "this whole subtree".
"""

from __future__ import annotations

import re
from collections import deque
from collections.abc import Sequence

from mde_contracts.spec import AppSpec, BuildSequence, BuildStep, FlowBlock, ParallelGroup
from mde_spec_loader.fragments import walk_nav
from mde_spec_loader.graph import build_ref_graph

FALLBACK_SLICE_SIZE = 5  # screens in the vertical slice when the spec has no flow
APP_DIR = "app"
SCREEN_EXT = ".tsx"
ROOT_SEGMENTS = ("index",)

STEP_NAMES: dict[str, str] = {
    "S0": "Scaffold from the stack template",
    "S1": "Theme and tokens",
    "S2": "Component kit variants",
    "S3": "Navigation shell and auth gate",
    "S4": "Data layer: types, API client, mock server",
    "S5": "Vertical slice: the primary flow end to end",
    "S6": "Screen groups in parallel",
    "S7": "Global behavior wiring: offline, locale, notifications, analytics, deep links",
    "S8": "Integrations: mocks and adapters",
    "S9": "Polish and accessibility",
    "S10": "Hand off to QA",
}

STEP_GATES: dict[str, str] = {
    "S0": "boots_on_web_preview",
    "S1": "token_file_validates",
    "S2": "kit_renders_in_all_variants",
    "S3": "all_routes_resolve",
    "S4": "typecheck_passes",
    "S5": "user_feedback",
    "S6": "screens_render_in_all_states_and_checks_pass",
    "S7": "flow_tests_pass",
    "S8": "adapters_typecheck",
    "S9": "lint_and_accessibility_checks_pass",
    "S10": "release_gate",
}


def primary_flow(spec: AppSpec) -> FlowBlock | None:
    """The flow the vertical slice builds.

    The first flow marked ``primary``; otherwise the flow with the most screens (ties go to the
    lowest id); None when there is no flow with a screen.
    """
    known = {s.id for s in spec.screens}
    usable = [f for f in spec.flows if any(s in known for s in f.screens)]
    for flow in usable:
        if flow.primary:
            return flow
    if not usable:
        return None
    return sorted(usable, key=lambda f: (-len({s for s in f.screens if s in known}), f.id))[0]


def _nav_screen_order(spec: AppSpec) -> list[str]:
    known = {s.id for s in spec.screens}
    ordered: list[str] = []
    for node in walk_nav(spec.navigation.root):
        if node.screen is not None and node.screen in known and node.screen not in ordered:
            ordered.append(node.screen)
    return ordered


def vertical_slice_screens(spec: AppSpec) -> tuple[FlowBlock | None, list[str]]:
    """(primary flow, ordered screen ids of the vertical slice)."""
    known = {s.id for s in spec.screens}
    flow = primary_flow(spec)
    if flow is not None:
        ordered: list[str] = []
        for screen_id in flow.screens:
            if screen_id in known and screen_id not in ordered:
                ordered.append(screen_id)
        return flow, ordered
    # no flow: the first navigation screen and what it reaches through actions
    nav_order = _nav_screen_order(spec) or [s.id for s in spec.screens[:1]]
    if not nav_order:
        return None, []
    graph = build_ref_graph(spec)
    seen = [nav_order[0]]
    queue = deque(seen)
    while queue and len(seen) < FALLBACK_SLICE_SIZE:
        current = queue.popleft()
        for edge in graph.out_edges(current, "go"):
            if edge.dst in known and edge.dst not in seen and len(seen) < FALLBACK_SLICE_SIZE:
                seen.append(edge.dst)
                queue.append(edge.dst)
    return None, seen


# --------------------------------------------------------------------------- file ownership


def route_segments(route: str) -> tuple[str, ...]:
    """Path segments of a route (``/product/[id]`` -> ``("product", "[id]")``; ``/`` -> index)."""
    parts = tuple(p for p in route.strip().split("/") if p)
    return parts or ROOT_SEGMENTS


def _file_glob(segments: Sequence[str]) -> str:
    return f"{APP_DIR}/{'/'.join(segments)}{SCREEN_EXT}"


def _common_prefix(paths: Sequence[tuple[str, ...]]) -> tuple[str, ...]:
    if not paths:
        return ()
    prefix = paths[0]
    for path in paths[1:]:
        size = 0
        while size < min(len(prefix), len(path)) and prefix[size] == path[size]:
            size += 1
        prefix = prefix[:size]
    return prefix


def owns_for_group(
    mine: Sequence[tuple[str, ...]], outside: Sequence[tuple[str, ...]]
) -> list[str]:
    """Path globs a group of screens owns, given the routes of every screen outside the group.

    A whole subtree (``app/checkout/**``) when the group's screens share a path prefix that no
    outside screen uses; otherwise one exact file glob per screen. Never overlaps another group.
    """
    common = _common_prefix(mine)
    if (
        common
        and common != ROOT_SEGMENTS  # the root index screen never owns a subtree
        and not any(o[: len(common)] == common for o in outside)
    ):
        globs = [f"{APP_DIR}/{'/'.join(common)}/**"]
        if any(m == common for m in mine):
            globs.append(_file_glob(common))
        return sorted(globs)
    return sorted({_file_glob(m) for m in mine})


def _split_glob(glob: str) -> tuple[bool, str]:
    return (True, glob[:-3]) if glob.endswith("/**") else (False, glob)


def globs_overlap(a: str, b: str) -> bool:
    """Could one path match both ``a`` and ``b``? (``dir/**`` subtree or an exact file path)."""
    a_dir, a_path = _split_glob(a)
    b_dir, b_path = _split_glob(b)
    if not a_dir and not b_dir:
        return a_path == b_path
    if a_dir and b_dir:
        return (
            a_path == b_path or a_path.startswith(b_path + "/") or b_path.startswith(a_path + "/")
        )
    if a_dir:
        return b_path.startswith(a_path + "/")
    return a_path.startswith(b_path + "/")


def _slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def screen_groups(spec: AppSpec, slice_ids: Sequence[str]) -> list[ParallelGroup]:
    """S6 groups for every screen that is not in the vertical slice."""
    in_slice = set(slice_ids)
    remaining = [s for s in spec.screens if s.id not in in_slice]
    flows = {f.id: f for f in spec.flows}

    def group_of(screen_id: str, own_flow: str | None, surface: str) -> tuple[str, str]:
        if own_flow is not None and own_flow in flows:
            return ("flow", own_flow)
        for flow in spec.flows:
            if screen_id in flow.screens:
                return ("flow", flow.id)
        return ("surface", surface)

    members: dict[tuple[str, str], list[str]] = {}
    for screen in remaining:
        members.setdefault(group_of(screen.id, screen.flow, screen.surface), []).append(screen.id)

    segments = {s.id: route_segments(s.route) for s in spec.screens}
    groups: list[ParallelGroup] = []
    used: set[str] = set()
    for (kind, key), ids in sorted(members.items(), key=lambda kv: kv[1][0]):
        base = _slug(flows[key].name) if kind == "flow" else _slug(key)
        base = base or key.lower()
        name = base
        counter = 2
        while name in used:
            name = f"{base}-{counter}"
            counter += 1
        used.add(name)
        mine = [segments[i] for i in ids]
        mine_set = set(ids)
        outside = [segments[i] for i in segments if i not in mine_set]
        groups.append(ParallelGroup(group=name, screens=ids, owns=owns_for_group(mine, outside)))
    return groups


# --------------------------------------------------------------------------- the sequence


def build_sequence(spec: AppSpec) -> BuildSequence:
    """S0..S10 from the spec's flows, screens and routes (deterministic)."""
    flow, slice_ids = vertical_slice_screens(spec)

    def step(step_id: str, load: list[str]) -> BuildStep:
        return BuildStep(id=step_id, name=STEP_NAMES[step_id], load=load, gate=STEP_GATES[step_id])

    s5 = BuildStep(
        id="S5",
        name=STEP_NAMES["S5"],
        load=[flow.id] if flow is not None else [],
        gate=STEP_GATES["S5"],
        flow=flow.id if flow is not None else None,
        screens=slice_ids,
        stop_for_feedback=True,
    )
    s6 = BuildStep(
        id="S6",
        name=STEP_NAMES["S6"],
        gate=STEP_GATES["S6"],
        parallel=screen_groups(spec, slice_ids),
    )
    return BuildSequence(
        steps=[
            step("S0", ["APP", "DESIGN"]),
            step("S1", ["DESIGN"]),
            step("S2", ["DESIGN"]),
            step("S3", ["NAV", "ROLES"]),
            step("S4", ["DATA", "API"]),
            s5,
            s6,
            step("S7", ["BEHAVIOR"]),
            step("S8", ["INTEGRATIONS"]),
            step("S9", ["DESIGN", "BEHAVIOR"]),
            step("S10", ["ACCEPT"]),
        ]
    )
